#!/usr/bin/env bash
# Read-only: MR-102 billing frequency discount in QA - frequency schedule tiers, quote line period formula fields, sample lines by frequency
q() { sf data query --query "$1" --target-org target --json 2>/dev/null | jq -c '[.result.records[]? | del(.attributes)]'; }
echo "SCHEDULES $(q "SELECT Name, IsActive, ScheduleType FROM PriceAdjustmentSchedule" | jq -c '[.[] | [.Name, .IsActive, .ScheduleType]]')"
for s in $(q "SELECT Id FROM PriceAdjustmentSchedule WHERE Name LIKE '%requenc%' OR Name LIKE '%Billing%'" | jq -r '.[].Id'); do
  echo "TIERS $s $(q "SELECT Product2.ProductCode, LowerBound, UpperBound, TierType, TierValue, CurrencyIsoCode FROM PriceAdjustmentTier WHERE PriceAdjustmentScheduleId = '$s' AND CurrencyIsoCode = 'USD' ORDER BY Product2.ProductCode, LowerBound LIMIT 16" | jq -c '[.[] | [.Product2.ProductCode, .LowerBound, .UpperBound, .TierValue]]')"
done
echo "QLI FIELDS $(sf sobject describe --sobject QuoteLineItem --target-org target --json 2>/dev/null | jq -c '[.result.fields[] | select(.name|test("Month|Period|Frequen|Billing";"i")) | select(.custom) | [.name, (.calculatedFormula // "") ]]')"
echo "LINES $(q "SELECT Quote.QuoteNumber, Product2.ProductCode, BillingFrequency, Quote.RLM_TermMonths__c, SubscriptionTerm, SubscriptionTermUnit, ListPrice, NetUnitPrice FROM QuoteLineItem WHERE Quote.QuoteNumber IN ('00000092','00000067','00000053','00000088','00000144') AND Product2.ProductCode IN ('MB-STR','MB-ACC','MB-ULT')" | jq -c '[.[] | [.Quote.QuoteNumber, .Product2.ProductCode, .BillingFrequency, .Quote.RLM_TermMonths__c, .SubscriptionTerm, .SubscriptionTermUnit, .ListPrice, .NetUnitPrice]]')"
echo "SEMI-ANNUAL SAMPLE $(q "SELECT Quote.QuoteNumber, Product2.ProductCode, Quote.RLM_TermMonths__c, Quantity, ListPrice, NetUnitPrice FROM QuoteLineItem WHERE BillingFrequency = 'SemiAnnual' AND Product2.ProductCode IN ('MB-STR','MB-ACC','MB-ULT') LIMIT 5" | jq -c '[.[] | [.Quote.QuoteNumber, .Product2.ProductCode, .Quote.RLM_TermMonths__c, .Quantity, .ListPrice, .NetUnitPrice]]')"
echo "ONE-TIME SAMPLE $(q "SELECT Quote.QuoteNumber, Product2.ProductCode, BillingFrequency, ListPrice, NetUnitPrice FROM QuoteLineItem WHERE PricebookEntry.ProductSellingModel.SellingModelType = 'OneTime' AND NetUnitPrice != null ORDER BY CreatedDate DESC LIMIT 6" | jq -c '[.[] | [.Quote.QuoteNumber, .Product2.ProductCode, .BillingFrequency, .ListPrice, .NetUnitPrice]]')"
